/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_baseDate.setValue(vCurDate);
    const sbmOptions = {
        id : "sbm_dts_design_releas_rsn",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_design_releas_rsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    scwin.search();
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    scwin.vCurrPageNo = 0;
    txb_TotalCnt.setValue("총건수 : ");
    let bndListStat = scwin.getChkValue(chb_ListStatCd);
    if (bndListStat === "0") {
        bndListStat = "2"; // 채권공시 해제법인

    }
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // 채권매매거래정지
        let url_list = "/UnfaithfulDesign.do?SCREN_ID=" + 'ULDSTF35820.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=srchInvstWarnBndLst&inputMessageId=INVSTWARN_BOND_INOUT" + "&outputMessageId=INVSTWARN_BOND_INOUT";
        let url_cond = "&ISUR_CD=" + txb_isur_cd_1.getValue() + "&BASE_DD=" + edt_baseDate.getValue() + "&LST_CD=" + chb_ListStatCd.getValue();

        // 그리드의 데이타 조회
        dts_invstwarn_list.DataID = encodeURI(url_list + url_cond);
        dts_invstwarn_list.reset();
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        // 채권매매거래정지해제
        let url_list = "/UnfaithfulDesign.do?SCREN_ID=" + 'ULDSTF35820.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=srchInvstWarnBndHistLst&inputMessageId=INVSTWARN_BOND_INOUT" + "&outputMessageId=TRHALTBOND_OUT";
        let url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&LST_CD=" + rdo_MKT_ID.getValue() + "&DESIGN_TP_CD=" + rdo_desnrels.getValue() + "&DESNRELS_RSN=" + cmb_rsn.getValue();

        // 그리드의 데이타 조회
        dts_invstwarn_hist_list.DataID = encodeURI(url_list + url_cond);
        dts_invstwarn_hist_list.reset();
    }
};

/**
 * @method
 * @name setContnIdList
 * @description 그리드에서 클릭 row의 변수셋팅 매매거래정지
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnIdList = function(obj) {
    scwin.gAcptNo = dts_invstwarn_list.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_invstwarn_list.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name setContnIdList2
 * @description 매매거래정지해제
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnIdList2 = function(obj) {
    scwin.gAcptNo = dts_invstwarn_hist_list.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_invstwarn_hist_list.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name grd_invstwarn_list_OnDblClick
 * @description grd_invstwarn_list 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_invstwarn_list_OnDblClick = async function(row, colid) {
    scwin.setContnIdList(row);
    if (colid === "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "ISU_NM") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF35820.xml');
    }
};

/**
 * @method
 * @name grd_trdhistbond_list_2_OnDblClick
 * @description grd_trdhistbond_list_2 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
