    scwin.setContnIdList2(row);
    if (colid === "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "DESNRELS_DD") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF35820.xml');
    }
};

/**
 * @method
 * @name dts_invstwarn_list_OnLoadError
 * @description dts_invstwarn_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
