 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_invstwarn_list_OnLoadCompleted = async function(rowcount) {
    if (dts_invstwarn_list.errorMsg) {
        await $c.win.alert(dts_invstwarn_list.errorMsg);
    } else {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
        // alert(txb_TotalCnt.value );

    }
};

